419	func scanProcessLaunches(t *testing.T, root string, report func(string, ...any)) (launches, wrappedCalls int) {
420		t.Helper()
421		// Launches that are not provider Git subprocesses, each reviewed:
422		allowedLaunchers := map[string]string{
423			"internal/gitutil/git.go:newCmd":                                      "the guarded constructor",
424			"internal/gitutil/git.go:newGitCmdWithCallerLocale":                   "the guarded caller-locale constructor",
425			"internal/gitutil/process_job_windows.go:newPathOutputCreationParent": "a suspended surrogate of this executable used as a job parent; it executes nothing",
426			"internal/cli/verify.go:runVerifyShell":                               "runs the user's own test command through their shell",
427			"internal/bench/worker.go:":                                           "benchmark harness, not shipped provider code",
428			"cmd/graph-bench/main.go:":                                            "benchmark harness that clones its corpus by design",
429		}
430		gitProgramWrappers := map[string]bool{"newCmd": true, "run": true, "runWithStderr": true}
431		passThroughWrappers := map[string]bool{"run": true, "runWithStderr": true}
432		valueCheckedWrappers := map[string]bool{"newCmd": true, "newGitCmdWithCallerLocale": true, "run": true, "runWithStderr": true}
433	
434		err := filepath.WalkDir(root, func(path string, entry fs.DirEntry, walkErr error) error {
435			if walkErr != nil {
436				return walkErr
437			}
438			if entry.IsDir() {
439				name := entry.Name()
440				if path != root && (strings.HasPrefix(name, ".") || name == "testdata" || name == "node_modules" || name == "bin") {
441					return filepath.SkipDir
442				}
443				return nil
444			}
445			if !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
446				return nil
447			}
448			rel, err := filepath.Rel(root, path)
449			if err != nil {
450				return err
451			}
452			rel = filepath.ToSlash(rel)
453			fset := token.NewFileSet()
454			file, err := parser.ParseFile(fset, path, nil, 0)
455			if err != nil {
456				return err
457			}
458			allowed := func(function string) bool {
459				_, whole := allowedLaunchers[rel+":"]
460				_, named := allowedLaunchers[rel+":"+function]
461				return whole || (function != "" && named)
462			}
463			// Map each file-local package name to its import path.
464			imports := map[string]string{}
465			for _, spec := range file.Imports {
466				importPath, _ := strconv.Unquote(spec.Path.Value)
467				name := importPath[strings.LastIndex(importPath, "/")+1:]
468				if spec.Name != nil {
469					name = spec.Name.Name
470				}
471				if name == "." && launchFunctions[importPath] != nil && !allowed("") {
472					report("%s: %s dot-imports %s, which hides its process-creation functions from this check", fset.Position(spec.Pos()), rel, importPath)
473				}
474				imports[name] = importPath
475			}
476			isGitutil := strings.HasPrefix(rel, "internal/gitutil/")
477			for _, decl := range file.Decls {
478				function := ""
479				where := "package-level declaration"
480				var body ast.Node = decl
481				if fn, ok := decl.(*ast.FuncDecl); ok {
482					function, where = fn.Name.Name, fn.Name.Name
483					if fn.Body == nil {
484						continue
485					}
486					body = fn.Body
487				}
488				calledWrappers := map[*ast.Ident]bool{}
489				selectedNames := map[*ast.Ident]bool{} // x.Name: a field or method, never a wrapper
490				isExecCmd := func(expr ast.Expr) bool {
491					selector, ok := expr.(*ast.SelectorExpr)
492					if !ok {
493						return false
494					}
495					pkg, ok := selector.X.(*ast.Ident)
496					return ok && imports[pkg.Name] == "os/exec" && selector.Sel.Name == "Cmd"
497				}
498				ast.Inspect(body, func(node ast.Node) bool {
499					switch node := node.(type) {
500					case *ast.SelectorExpr:
501						selectedNames[node.Sel] = true
502						pkg, ok := node.X.(*ast.Ident)
503						if !ok {
504							return true
505						}
506						importPath := imports[pkg.Name]
507						if launchFunctions[importPath][node.Sel.Name] {
508							launches++
509							if !allowed(function) {
510								report("%s: %s references %s.%s outside the guarded Git constructors", fset.Position(node.Pos()), where, importPath, node.Sel.Name)
511							}
512						}
513					case *ast.CompositeLit:
514						if isExecCmd(node.Type) {
515							report("%s: %s builds an exec.Cmd literal; build Git commands with newCmd", fset.Position(node.Pos()), where)
516						}
517					case *ast.CallExpr:
518						ident, ok := node.Fun.(*ast.Ident)
519						if ok && ident.Name == "new" && len(node.Args) == 1 && isExecCmd(node.Args[0]) {
520							report("%s: %s allocates an exec.Cmd; build Git commands with newCmd", fset.Position(node.Pos()), where)
521						}
522						if ok && valueCheckedWrappers[ident.Name] {
523							calledWrappers[ident] = true
524						}
525						if !isGitutil || !ok || !gitProgramWrappers[ident.Name] {
526							return true
527						}
528						if len(node.Args) < 3 {
529							return true
530						}
531						wrappedCalls++
532						if lit, ok := node.Args[2].(*ast.BasicLit); ok && lit.Kind == token.STRING && lit.Value == `"git"` {
533							return true
534						}
535						if passThroughWrappers[function] || function == "newCmd" {
536							return true // run/runWithStderr forward their own name argument to newCmd
537						}
538						report("%s: %s calls %s with a program other than the literal \"git\"; newCmd would skip the Git environment",
539							fset.Position(node.Pos()), where, ident.Name)
540					case *ast.Ident:
541						if isGitutil && valueCheckedWrappers[node.Name] && !calledWrappers[node] && !selectedNames[node] {
542							if fn, ok := decl.(*ast.FuncDecl); !ok || fn.Name != node {
543								report("%s: %s uses %s as a value; call it directly so the program argument stays checkable", fset.Position(node.Pos()), where, node.Name)
544							}
545						}
546					}
547					return true
548				})
549			}
550			return nil
551		})
552		if err != nil {
553			t.Fatal(err)
554		}
555		return launches, wrappedCalls
556	}
