import (
	ex "os/exec"
	. "syscall"
)

var launch = ex.CommandContext

func fetch() { _ = ex.Command("git", "fetch").Run(); _ = launch; _ = Getpid }

func indirect() { f := newCmd; _ = f; _ = run(nil, "", program, "fetch") }

func newCmd() {}
func run(...any) error { return nil }

var program = "git"
var _ = ex.Cmd{}
`
